import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Cloud contracts, synchronization and review","description":"","frontmatter":{"title":"Cloud contracts, synchronization and review","docId":"developer.cloud","translationKey":"developer.cloud","locale":"en","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"06ae46545d1366d4f456c78a0e6583ea0338afbd496467e4d25b3abe1a5430fb","translationRevision":"06ae46545d1366d4f456c78a0e6583ea0338afbd496467e4d25b3abe1a5430fb","order":180},"headers":[],"relativePath":"en/developer/cloud.md","filePath":"en/developer/cloud.md","lastUpdated":1794611623000}'),o={name:"en/developer/cloud.md"};function n(s,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="cloud-contracts-synchronization-and-review" tabindex="-1">Cloud contracts, synchronization and review <a class="header-anchor" href="#cloud-contracts-synchronization-and-review" aria-label="Permalink to &quot;Cloud contracts, synchronization and review {#cloud-contracts-synchronization-and-review}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Develop account configuration and catalog features against the provisioned Cloud instance. Local-only operation remains valid. For authenticated work, use a dedicated test account/backend and the native session handoff; this documentation does not establish production bearer or two-device acceptance.</p><p>The verified contract owner is <a href="https://github.com/nglmercer/RemakeBackend" target="_blank" rel="noreferrer">nglmercer/RemakeBackend</a>, with <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V2.md" target="_blank" rel="noreferrer">v2 configuration contracts</a> and additive <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V3.md" target="_blank" rel="noreferrer">v3 surfaces</a>. Backend-owned portable types and client transport are represented locally in <code>crates/cloud-contracts</code> and <code>crates/cloud-client</code>. Desktop durability and authentication remain host responsibilities.</p><h2 id="gate-and-stage-operations" tabindex="-1">Gate and stage operations <a class="header-anchor" href="#gate-and-stage-operations" aria-label="Permalink to &quot;Gate and stage operations {#gate-and-stage-operations}&quot;">​</a></h2><ol><li>Discover native methods with <code>rpc.discover</code>; an older host can retain legacy views.</li><li>Let the host check the instance&#39;s <code>/api/v2/capabilities</code> before using its gated feature endpoint. Never hardcode an advertised server capability into a browser-only flag.</li><li>Use the operator-provisioned origin. Release builds do not accept arbitrary runtime origin replacements.</li><li>Preview migration and conflicts, retain frozen bases and uncertain writes, and submit only the reviewed operation.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync.v2.migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> globals.typed.replace</span></span></code></pre></div><p>These inspect schemas; they do not migrate an account or save variable values.</p><h2 id="current-implementation" tabindex="-1">Current implementation <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Current implementation {#current-implementation}&quot;">​</a></h2><p>V2 has native state/store/coordinator, guarded v1 migration, conflict review, rebuild and installed-plugin reconciliation paths. Adoption is explicit and account scoped; unmarked legacy installs remain on their legacy path. Full two-Desktop acceptance and some product adapters remain incomplete. The account-wide write-epoch setup has irreversible server consequences explained by its migration review.</p><p>V3 adds catalog, teams, integrations, assets, overlays and package surfaces behind capabilities. Catalog metadata does not replace signed plugin verification. Template/profile import uses the owner library journal; review enabled values at application/profile import. Package application records interrupted steps rather than replaying them automatically. Cloud relay read access must not be confused with direct collaboration mutation authority.</p><h2 id="expected-result-and-recovery" tabindex="-1">Expected result and recovery <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Expected result and recovery {#expected-result-and-recovery}&quot;">​</a></h2><p>Configuration changes retain identity, revision and review boundaries. Automations Changes is local-only; reviewed Variables uses real typed native methods and does not sync raw values. Overlay Changes is not merged. On conflict, compare base/local/fresh Cloud records; on unknown acknowledgement, resolve the retained intent. A retryable HTTP error never authorizes repeating a mutation. <a href="./collaboration.html">Collaboration</a> covers running-host authority separately.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p><code>TIKTOOLS_CLOUD_ORIGIN</code> resolution is runtime → compiled value → default in debug, but compiled value → default in release: release ignores runtime overrides. Empty, <code>off</code> or <code>none</code> disables only at the applicable configuration layer. A valid value is an HTTPS origin without credentials, path, query or fragment; HTTP is limited to explicit loopback. For isolated debug use <code>TIKTOOLS_CLOUD_ORIGIN=http://127.0.0.1:8787 bun run start</code>; compile release with <code>TIKTOOLS_CLOUD_ORIGIN=https://cloud.example bun scripts/task.ts rust build -p tiktools-desktop --release --locked</code>. A saved identity from another origin cannot be restored; inspect origin/account before authenticating again. A compiled default is not evidence of deployed service availability.</p><p>Follow <a href="./../user/cloud/changes.html#operational-details">migration and per-mode recovery</a>. Coordinate all devices before irreversible write-epoch policy, retain preview counts and original outcomes, re-read state after ambiguous barriers and never repeat a barrier to test whether the first ran. Product-conflict recovery freezes reviewed inputs and revision; stale review must be rebuilt before resume, which itself dispatches no Cloud write.</p>`,16)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
